const params=new URLSearchParams(location.search);const scene=params.get('scene')||'daily';const direction=params.get('direction')||'b';const progress=Math.max(0,Math.min(1,Number(params.get('p')||1)));if(params.get('capture')==='1')document.body.classList.add('capture');document.body.classList.add(`dir-${direction}`);document.documentElement.style.setProperty('--progress',progress);
const signed=(v,d=1)=>`${v>=0?'+':''}${Number(v).toFixed(d)}`;const pcent=v=>`${signed(v,1)}%`;const short=n=>n.replace('ETF易方达','ETF·易方达').replace('ETF华安','ETF·华安');
function footer(m){return `<footer class="footer"><div>${m.disclaimer}</div><div class="source">交易日 ${m.trade_date}<br>数据源：项目本地 etf.db</div></footer>`}
function spark(points,color){const v=points.map(x=>x.shares_yi),lo=Math.min(...v),hi=Math.max(...v),span=hi-lo||1,xy=v.map((x,i)=>`${i/(v.length-1)*100},${31-(x-lo)/span*27}`).join(' ');return `<svg class="spark" viewBox="0 0 100 34" preserveAspectRatio="none"><line x1="0" y1="31" x2="100" y2="31" stroke="#26384d"/><polyline points="${xy}" fill="none" stroke="${color}" stroke-width="2.5" vector-effect="non-scaling-stroke"/></svg>`}
function chart(s){const W=870,H=520,L=58,R=18,T=20,B=50,all=s.flatMap(x=>[x.shares_index,x.price_index]),lo=Math.floor(Math.min(...all)/10)*10-5,hi=Math.ceil(Math.max(...all)/10)*10+5,x=i=>L+i/(s.length-1)*(W-L-R),y=v=>T+(hi-v)/(hi-lo)*(H-T-B),path=k=>s.map((d,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(d[k]).toFixed(1)}`).join(' '),grid=[lo,(lo+hi)/2,hi].map(v=>`<g><line x1="${L}" y1="${y(v)}" x2="${W-R}" y2="${y(v)}" stroke="#213248"/><text x="0" y="${y(v)+5}" fill="#718197" font-size="15">${v.toFixed(0)}</text></g>`).join(''),ticks=[0,5,10,15,20].map(i=>`<text x="${x(i)}" y="508" text-anchor="middle" fill="#718197" font-size="14">${s[i].date.slice(5)}</text>`).join('');return `<svg class="main-chart" viewBox="0 0 ${W} ${H}">${grid}${ticks}<line x1="${L}" y1="${y(100)}" x2="${W-R}" y2="${y(100)}" stroke="#516177" stroke-dasharray="6 6"/><path d="${path('shares_index')}" fill="none" stroke="#19d3c5" stroke-width="4.5" pathLength="1" stroke-dasharray="1" stroke-dashoffset="${1-progress}"/><path d="${path('price_index')}" fill="none" stroke="#ff9d4d" stroke-width="4.5" pathLength="1" stroke-dasharray="1" stroke-dashoffset="${1-progress}"/></svg>`}
function daily(d){const rows=d.rankings.daily_reference_increase.slice(0,5),max=rows[0].reference_value_yi,c=d.rankings.counts;return `<article class="frame"><div class="content"><header><div class="eyebrow">自制ETF份额统计榜 · DAILY 01</div><h1 class="title">ETF份额异动龙虎榜</h1><div class="subtitle">${d.meta.trade_date}｜日榜</div></header><div class="rule"></div><section class="finding"><span class="tag">今日发现</span><strong>宽基ETF包揽前五，<span class="up num">300ETF +104.98亿元</span>居首</strong></section><div class="section-head"><h2>份额增加对应收盘参考市值 TOP 5</h2><span>单位：亿元</span></div><section class="rank-list">${rows.map((r,i)=>`<div class="rank-row ${i===0?'hero':''}"><div class="rank-no num">${String(i+1).padStart(2,'0')}</div><div><div class="fund-name">${short(r.name)}</div><div class="fund-code">${r.code} · 份额 ${pcent(r.share_change_pct)} · 价格 ${pcent(r.price_change_pct)}</div></div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(4,r.reference_value_yi/max*100)}%"></div></div><div class="rank-value"><strong class="num">${signed(r.reference_value_yi,1)}</strong><span>收盘参考市值</span></div></div>`).join('')}</section><section class="market-strip"><div class="market-stat"><span>份额增加</span><strong class="up num">${c.increase}只</strong></div><div class="market-stat"><span>份额减少</span><strong class="down num">${c.decrease}只</strong></div><div class="market-stat"><span>份额持平</span><strong class="muted num">${c.flat}只</strong></div></section>${footer(d.meta)}</div></article>`}
function weekPanel(title,rows,pos){const color=pos?'#ff665f':'#2ed28b';return `<section class="weekly-panel panel"><div class="panel-head"><h2>${title}</h2><span>股票ETF主榜 · 收盘参考市值</span></div><div class="weekly-items">${rows.map((r,i)=>`<div class="weekly-item"><div class="rank">${i+1}</div><div><div class="weekly-name">${short(r.name)}</div><div class="weekly-meta">${r.code} · ${pos?r.positive_days_5:r.negative_days_5}/5日同向</div>${spark(r.series_5,color)}</div><div class="weekly-value ${pos?'up':'down'} num">${signed(r.reference_5d_yi,1)}亿</div></div>`).join('')}</div></section>`}
function weekly(d){const inc=d.rankings.continuous_increase_5d.slice(0,5),dec=d.rankings.weekly_decrease_5d.slice(0,5);return `<article class="frame weekly-frame"><div class="content"><header><div class="eyebrow">自制ETF份额统计榜 · WEEKLY 02</div><h1 class="title">本周哪些ETF份额持续增加？</h1><div class="subtitle">${d.meta.week_start} — ${d.meta.trade_date}｜5个交易日</div></header><div class="rule"></div><section class="finding"><span class="tag">结构变化</span><strong>连续增加榜由宽基主导，<span class="up">持续性比单日名次更重要</span></strong></section><div class="weekly-stack">${weekPanel('连续增加 TOP 5',inc,true)}${weekPanel('累计减少 TOP 5',dec,false)}</div><div class="week-note panel"><strong>微型趋势显示6个观测点</strong><span>“5日同向”按5个日变化计算</span></div>${footer(d.meta)}</div></article>`}
function focus(d){const f=d.focus['588000'];return `<article class="frame"><div class="content"><header class="focus-head"><div><div class="eyebrow">榜首深读 · FOCUS 03</div><h1 class="title">${f.name}</h1><div class="ticker">${f.code}</div></div><div class="badge">20日价格—份额背离</div></header><div class="rule"></div><section class="metric-grid"><div class="metric"><label>当前份额</label><strong class="num">${f.current_shares_yi.toFixed(1)}</strong><small>亿份</small></div><div class="metric"><label>单日份额变化</label><strong class="num up">${signed(f.delta_shares_yi,1)}</strong><small>亿份 · 稳健Z ${f.robust_z_60??'N/A'}</small></div><div class="metric"><label>20日份额变化</label><strong class="num up">${pcent(f.share_change_20d_pct)}</strong><small>${signed(f.delta_20d_shares_yi,1)}亿份</small></div><div class="metric"><label>同期价格变化</label><strong class="num down">${pcent(f.price_change_20d_pct)}</strong><small>收盘价口径</small></div></section><section class="chart-panel panel"><div class="chart-head"><div><h2>价格与份额标准化指数</h2><div class="chart-note">${d.meta.window_20_start} = 100｜同一坐标轴，避免双轴误读</div></div><div class="legend"><span><i style="background:#19d3c5"></i>份额</span><span><i style="background:#ff9d4d"></i>价格</span></div></div>${chart(f.series_20)}</section><section class="focus-conclusion">过去20个交易日，科创50ETF份额增加 <strong class="up num">48.03%</strong>，同期价格下跌 <strong class="down num">16.16%</strong>。这是可验证的统计背离，不是“资金抄底”的因果结论。</section>${footer(d.meta)}</div></article>`}
function divergence(d){return `<article class="frame"><div class="content"><header><div class="eyebrow">数据专题 · DIVERGENCE 04</div><h1 class="title">价格跌了，ETF份额为什么还在增加？</h1><div class="subtitle">20个交易日｜${d.meta.window_20_start} — ${d.meta.trade_date}</div></header><div class="rule"></div><p class="div-intro">先看事实：三个样本都出现“价格向下、份额向上”。这说明申赎需求发生变化，但不能识别投资者身份与动机。</p><section class="div-stack">${d.divergence_cases.map((f,i)=>{const sw=Math.min(100,30+Math.abs(f.share_change_20d_pct)),pw=Math.min(100,30+Math.abs(f.price_change_20d_pct)*2);return `<div class="div-card panel"><div><div class="case">CASE 0${i+1}</div><h2>${short(f.name)}</h2><div class="code">${f.code}</div></div><div class="arrow-pair"><div class="arrow-line"><label>份额</label><div class="track"><div class="fill" style="--w:${sw}%;--c:#ff665f"></div></div><strong class="up num">${pcent(f.share_change_20d_pct)}</strong></div><div class="arrow-line"><label>价格</label><div class="track"><div class="fill" style="--w:${pw}%;--c:#2ed28b"></div></div><strong class="down num">${pcent(f.price_change_20d_pct)}</strong></div></div><div class="div-big"><label>20日收盘参考市值</label><strong class="num">${signed(f.reference_20d_yi,1)}亿</strong></div><p class="div-copy">${i===0?'大盘宽基代表，最新单日和20日份额变化都较突出。':i===1?'科创宽基代表，20日份额增加267.00亿份。':'成长风格代表，价格回撤更深，份额增幅达68.83%。'}</p></div>`}).join('')}</section><div class="not-causal"><strong>可以说：</strong>份额在价格回撤期增加。　<strong>不能直接说：</strong>主力抄底或真实净流入。</div>${footer(d.meta)}</div></article>`}
function daily10(d){const rows=d.rankings.daily_reference_increase.slice(0,10);return `<article class="frame"><div class="content"><header><div class="eyebrow">ENDING BOARD · TOP 10</div><h1 class="title">ETF份额异动龙虎榜</h1><div class="subtitle">${d.meta.trade_date}｜结束定格版</div></header><div class="rule"></div><section class="finding"><span class="tag">TOP 10</span><strong>份额增加对应收盘参考市值｜请暂停查看</strong></section><section class="compact-list">${rows.map((r,i)=>`<div class="compact-row"><div class="rank num">${String(i+1).padStart(2,'0')}</div><div class="name">${short(r.name)}<small>${r.code} · 份额 ${pcent(r.share_change_pct)}</small></div><div class="value num">${signed(r.reference_value_yi,1)}</div></div>`).join('')}</section><div class="not-causal">TOP5用于正文动态播报；TOP10只用于结束定格。单位统一为亿元。</div>${footer(d.meta)}</div></article>`}
fetch('../runs/latest/content.json').then(r=>r.json()).then(d=>{const map={daily,weekly,focus,divergence,daily10};document.getElementById('stage').innerHTML=(map[scene]||daily)(d);window.__renderReady=true}).catch(e=>{document.getElementById('stage').textContent=`加载失败：${e.message}`;window.__renderReady=false});
